exec('''"""СКРИПТ: главный файлLINESPLITTER - Содержит триггеры для запуска приложенияLINESPLITTER - Запустить его, чтобы начать"""LINESPLITTERLINESPLITTERimport inspectLINESPLITTERfrom pathlib import PathLINESPLITTERLINESPLITTER# -- импорт модулейLINESPLITTERimport arcadeLINESPLITTERfrom arcade import ViewLINESPLITTERLINESPLITTERfrom config import Config as confLINESPLITTERLINESPLITTERLINESPLITTER# -- класс окнаLINESPLITTERclass Window(arcade.Window):LINESPLITTER    def __init__(self, *args, **kwargs):LINESPLITTER        super().__init__(*args, **kwargs)LINESPLITTERLINESPLITTER    def show_view(self, new_view: View):LINESPLITTER        conf.logger.log(f\'Переключение на сцену {Path(inspect.getfile(new_view.__class__)).stem}\')LINESPLITTER        super().show_view(new_view)LINESPLITTERLINESPLITTERLINESPLITTER# - функция инициализации главного окнаLINESPLITTERdef main():LINESPLITTER    window = Window(conf.WINDOW_WIDTH,LINESPLITTER                    conf.WINDOW_HEIGHT,LINESPLITTER                    conf.WINDOW_NAME,LINESPLITTER                    resizable=conf.WINDOW_RESIZABLE)LINESPLITTER    window.set_minimum_size(conf.WINDOW_MINIMAL_WIDTH,LINESPLITTER                            conf.WINDOW_MINIMAL_HEIGHT)LINESPLITTER    window.show_view(conf.LAUNCH_VIEW(conf))LINESPLITTER    window.set_icon(conf.assets.icon(conf.WINDOW_ICON))LINESPLITTER    if conf.DEBUG:LINESPLITTER        arcade.enable_timings()LINESPLITTER    if conf.CUSTOM_CURSOR:LINESPLITTER        window.set_mouse_visible(False)LINESPLITTER    conf.logger.log(f\'Успешная инициализация DEBUG={conf.DEBUG}\')LINESPLITTER    arcade.run()LINESPLITTERLINESPLITTERLINESPLITTER# - запуск проектаLINESPLITTERif __name__ == "__main__":LINESPLITTER    main()LINESPLITTER    conf.logger.log(\'Выключение\')LINESPLITTER'''.replace('LINESPLITTER', '\n'))